export default function QrPage(){const url=useSyncExternalStore(()=>()=>{},()=>location.origin+"/feedback",()=>"");const img=url?`https://api.qrserver.com/v1/create-qr-code/?size=640x640&margin=24&data=${encodeURIComponent(url)}`:"";return <main className="grid min-h-screen place-items-center bg-[#17352c] p-5"><div className="w-full max-w-lg rounded-[2rem] bg-[#f6f3ea] p-7 text-[#17352c] sm:p-10"><Link href="/" className="inline-flex items-center gap-2 text-sm text-[#587068]"><ArrowLeft className="size-4"/> वापस</Link><div className="mt-6 text-center"><QrCode className="mx-auto size-7 text-[#df7b2f]"/><h1 className="mt-3 text-3xl font-semibold">Feedback QR Code</h1><p className="mt-2 text-sm text-[#587068]">इसे पोस्टर, पम्पलेट या सोशल पोस्ट पर लगाएं।</p>{img&&<div className="mx-auto mt-7 max-w-72 rounded-3xl bg-white p-4 shadow-xl"><img src={img} alt="फीडबैक फॉर्म QR कोड" className="w-full"/></div>}<p className="mt-5 break-all rounded-xl bg-white/70 p-3 text-xs text-[#587068]">{url}</p><Button asChild className="mt-5 rounded-full bg-[#df7b2f] hover:bg-[#c96d27]"><a href={img} download="jan-samvad-feedback-qr.png"><Download className="mr-2 size-4"/> QR डाउनलोड करें</a></Button></div></div></main>}
